class Solution {
public:
    int countBalls(int lowLimit, int highLimit) {
        int boxes[46] = {0};
        int best = 0;
        for (int i = lowLimit; i <= highLimit; ++i) {
            int s = 0, x = i;
            while (x > 0) {
                s += x % 10;
                x /= 10;
            }
            boxes[s]++;
            if (boxes[s] > best) best = boxes[s];
        }
        return best;
    }
};
